import jsPDF from "jspdf";

// Optional: base64-encoded Nexvoide logo (PNG). If empty, text logo is used.
// You can generate a data URL in the browser and paste it here.
// Example: const NEXVOIDE_LOGO_DATA_URL = "data:image/png;base64,....";
const NEXVOIDE_LOGO_DATA_URL = "data:image/png;base64,";

// Shared helper: convert HEX color to RGB (0-255)
function hexToRgb(hex) {
  const h = String(hex || "").replace("#", "");
  const bigint = parseInt(h, 16);
  if (Number.isNaN(bigint) || h.length !== 6) {
    return { r: 0, g: 0, b: 0 };
  }
  return {
    r: (bigint >> 16) & 255,
    g: (bigint >> 8) & 255,
    b: bigint & 255,
  };
}

/**
 * Generate a premium-looking PDF invoice for an agency, brand, or freelance profile
 * for the current month.
 */
export function generateInvoicePDF(
  entity,
  projects,
  entityType,
  currency = "PKR",
  rate = 280
) {
  const doc = new jsPDF("p", "pt", "a4");
  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();
  const margin = 40;
  const contentWidth = pageWidth - margin * 2;

  // Premium color palette
  const COLORS = {
    primary: "#1a56db", // deep blue
    secondary: "#1a56db", // also blue for totals / pills
    dark: "#020617",
    medium: "#64748b",
    light: "#f3f4f6",
    border: "#e5e7eb",
    white: "#ffffff",
  };

  const primary = hexToRgb(COLORS.primary);
  const secondary = hexToRgb(COLORS.secondary);
  const dark = hexToRgb(COLORS.dark);
  const medium = hexToRgb(COLORS.medium);
  const light = hexToRgb(COLORS.light);
  const border = hexToRgb(COLORS.border);
  const white = hexToRgb(COLORS.white);

  // Get current month in YYYY-MM format
  const now = new Date();
  const currentMonth = `${now.getFullYear()}-${String(
    now.getMonth() + 1
  ).padStart(2, "0")}`;
  const monthName = now.toLocaleString("default", {
    month: "long",
    year: "numeric",
  });

  // Filter projects by entity and month (keep your existing business logic)
  const entityProjects = projects.filter((p) => {
    const agencyId = p.agencyId || p.agency_id;
    const brandId = p.brandId || p.brand_id;
    const profileId = p.profileId || p.profile_id;

    let matchesEntity = false;

    if (entityType === "agency") {
      matchesEntity =
        agencyId === entity.id || String(agencyId) === String(entity.id);
    } else if (entityType === "brand") {
      matchesEntity =
        brandId === entity.id || String(brandId) === String(entity.id);
    } else if (entityType === "profile") {
      matchesEntity =
        profileId === entity.id ||
        String(profileId) === String(entity.id) ||
        (p.platform === entity.platform && p.clientName === entity.name);
    }

    if (!matchesEntity) return false;

    const projectDate = p.endDate || p.end_date || p.startDate || p.start_date;
    if (!projectDate) return false;

    let dateObj;
    if (projectDate instanceof Date) {
      dateObj = projectDate;
    } else if (typeof projectDate === "string") {
      dateObj = new Date(projectDate);
      if (isNaN(dateObj.getTime())) return false;
    } else {
      return false;
    }

    const projectYear = dateObj.getFullYear();
    const projectMonth = String(dateObj.getMonth() + 1).padStart(2, "0");
    const projectMonthStr = `${projectYear}-${projectMonth}`;

    return projectMonthStr === currentMonth;
  });

  // Currency conversion helper
  const convertCurrency = (amount, fromCurrency) => {
    if (fromCurrency === currency) return amount;
    if (fromCurrency === "USD" && currency === "PKR") return amount * rate;
    if (fromCurrency === "PKR" && currency === "USD") return amount / rate;
    return amount;
  };

  // Rows + totals
  let totalValue = 0;
  const projectRows = entityProjects.map((p) => {
    const projectAmount = Number(p.amount || 0);
    const projectCurrency = p.currency || "USD";
    const convertedAmount = convertCurrency(projectAmount, projectCurrency);
    totalValue += convertedAmount;

    const projectName = p.projectName || p.project_name || "Unnamed Project";
    const quantity =
      p.quantity || p.revisionQuantity || p.revision_quantity || "-";

    return {
      name: projectName,
      quantity,
      value: convertedAmount,
    };
  });

  const formatCurrency = (amount) =>
    new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: currency === "PKR" ? "PKR" : "USD",
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }).format(amount);

  // === Layout helpers ===

  const drawHeader = () => {
    const headerH = 90;

    // Full-width dark header so white logo is clearly visible
    // Hex #010333 → rgb(1, 3, 51)
    doc.setFillColor(1, 3, 51);
    doc.rect(0, 0, pageWidth, headerH, "F");

    // Logo: prefer image, fall back to text logo (add some top margin)
    const logoY = 28;

    if (NEXVOIDE_LOGO_DATA_URL) {
      // Assume a horizontal logo; slightly smaller for better spacing
      const logoWidth = 146;
      const logoHeight = 32;
      try {
        doc.addImage(
          NEXVOIDE_LOGO_DATA_URL,
          "PNG",
          margin,
          logoY,
          logoWidth,
          logoHeight
        );
      } catch {
        // If image fails, fall back to a simple text mark
  doc.setFont("helvetica", "bold");
        doc.setFontSize(22);
        doc.setTextColor(255, 255, 255);
        doc.text("NEXVOIDE", margin, 32);
      }
    } else {
      // Text-only logo when no image is configured
      doc.setFont("helvetica", "bold");
      doc.setFontSize(22);
      doc.setTextColor(255, 255, 255);
      doc.text("NEXVOIDE", margin, 42);
    }

    // Right side header info (no box – just clean text)
    const rightX = pageWidth - margin;

    // INVOICE label
    doc.setFont("helvetica", "bold");
    doc.setFontSize(16);
    doc.setTextColor(255, 255, 255);
    doc.text("INVOICE", rightX, 38, { align: "right" });

    // Invoice number
    const invoiceNum = `INV-${now.getFullYear()}${String(
    now.getMonth() + 1
  ).padStart(2, "0")}${String(now.getDate()).padStart(2, "0")}`;
  doc.setFont("helvetica", "normal");
    doc.setFontSize(10);
    doc.setTextColor(199, 210, 254);
    doc.text(invoiceNum, rightX, 54, { align: "right" });

    // Period text to visually fill header
    doc.setFontSize(9.5);
    doc.setTextColor(148, 163, 184);
    doc.text(`Period: ${monthName}`, rightX, 68, { align: "right" });
  };

  const drawFromTo = () => {
    let yPos = 130;

    // From (company)
    const boxH = 90;
    const halfW = (contentWidth - 10) / 2;

    doc.setFillColor(light.r, light.g, light.b);
    doc.roundedRect(margin, yPos, halfW, boxH, 8, 8, "F");

  doc.setFont("helvetica", "bold");
    doc.setFontSize(9);
    doc.setTextColor(medium.r, medium.g, medium.b);
    doc.text("FROM", margin + 18, yPos + 20);

  doc.setFont("helvetica", "bold");
    doc.setFontSize(15);
    doc.setTextColor(dark.r, dark.g, dark.b);
    doc.text("Nexvoide", margin + 18, yPos + 38);

  doc.setFont("helvetica", "normal");
    doc.setFontSize(10);
    doc.setTextColor(medium.r, medium.g, medium.b);
    doc.text("Suite 101, Tech Park", margin + 18, yPos + 56);
    doc.text("Lahore, Punjab 54000", margin + 18, yPos + 70);
    doc.text("support@nexvoide.com", margin + 18, yPos + 84);

    // To (client)
    const toX = margin + halfW + 10;
    doc.setFillColor(light.r, light.g, light.b);
    doc.roundedRect(toX, yPos, halfW, boxH, 8, 8, "F");

  doc.setFont("helvetica", "bold");
    doc.setFontSize(9);
    doc.setTextColor(medium.r, medium.g, medium.b);
    doc.text("BILL TO", toX + 18, yPos + 20);

  doc.setFont("helvetica", "bold");
    doc.setFontSize(15);
    doc.setTextColor(dark.r, dark.g, dark.b);
    const clientName = doc.splitTextToSize(
      String(entity.name || "Client"),
      halfW - 36
    );
    doc.text(clientName, toX + 18, yPos + 38);

  doc.setFont("helvetica", "normal");
    doc.setFontSize(10);
    doc.setTextColor(medium.r, medium.g, medium.b);
    let lineY = yPos + 56;
    if (entity.email) {
      doc.text(String(entity.email), toX + 18, lineY);
      lineY += 14;
    }
    if (entity.city || entity.country) {
      const addr = [entity.city, entity.country].filter(Boolean).join(", ");
      doc.text(addr, toX + 18, lineY);
    }

    return yPos + boxH + 20;
  };

  const drawMetaCards = (startY) => {
    const details = [
      { label: "INVOICE DATE", value: now.toISOString().slice(0, 10) },
      {
        label: "DUE DATE",
        value: new Date(
    now.getFullYear(),
    now.getMonth(),
    now.getDate() + 15
        )
          .toISOString()
          .slice(0, 10),
      },
      { label: "PERIOD", value: monthName },
      { label: "CURRENCY", value: currency },
    ];

    const gap = 10;
    const cardW = (contentWidth - gap * 3) / 4;
    const cardH = 70;

    details.forEach((d, idx) => {
      const x = margin + idx * (cardW + gap);
      doc.setFillColor(white.r, white.g, white.b);
      doc.setDrawColor(border.r, border.g, border.b);
      doc.setLineWidth(1);
      doc.roundedRect(x, startY, cardW, cardH, 8, 8, "FD");

    doc.setFont("helvetica", "bold");
      doc.setFontSize(8.5);
      doc.setTextColor(primary.r, primary.g, primary.b);
      const labelWidth = doc.getTextWidth(d.label);
      doc.text(d.label, x + (cardW - labelWidth) / 2, startY + 20);

    doc.setFont("helvetica", "bold");
      doc.setFontSize(13);
      doc.setTextColor(dark.r, dark.g, dark.b);
      const valueWidth = doc.getTextWidth(d.value);
      doc.text(d.value, x + (cardW - valueWidth) / 2, startY + 44);
    });

    return startY + cardH + 24;
  };

  const drawProjectsTable = (startY) => {
    const headerH = 30;
    const rowH = 40;

    const colDescW = contentWidth * 0.5;
    const colQtyW = contentWidth * 0.15;
    const colAmtW = contentWidth * 0.35;

    const tableTop = startY + 10;

    // Header background
    doc.setFillColor(primary.r, primary.g, primary.b);
    doc.roundedRect(margin, tableTop, contentWidth, headerH, 6, 6, "F");

  doc.setFont("helvetica", "bold");
    doc.setFontSize(10.5);
    doc.setTextColor(white.r, white.g, white.b);

    let x = margin + 14;
    const headerY = tableTop + 20;
    doc.text("DESCRIPTION", x, headerY);

    x = margin + colDescW + colQtyW / 2;
    doc.text("QTY", x, headerY, { align: "center" });

    x = margin + colDescW + colQtyW + colAmtW - 14;
    doc.text("AMOUNT", x, headerY, { align: "right" });

    let y = tableTop + headerH;

    if (projectRows.length === 0) {
      y += 24;
  doc.setFont("helvetica", "normal");
  doc.setFontSize(11);
      doc.setTextColor(medium.r, medium.g, medium.b);
      doc.text(
        "No projects found for this period.",
        margin + contentWidth / 2,
        y,
        { align: "center" }
      );
      y += 40;
      return y;
    }

    projectRows.forEach((row, idx) => {
      if (y > pageHeight - 160) {
        doc.addPage();
        y = margin + 40;
      }

      // zebra stripe
      if (idx % 2 === 0) {
        doc.setFillColor(248, 250, 252);
        doc.rect(margin, y, contentWidth, rowH, "F");
      }

      doc.setFont("helvetica", "normal");
      doc.setFontSize(11);
      doc.setTextColor(dark.r, dark.g, dark.b);

      // Description
      const desc = doc.splitTextToSize(row.name, colDescW - 24);
      doc.text(desc, margin + 14, y + 22);

      // Qty (center)
      const qtyX = margin + colDescW + colQtyW / 2;
      doc.text(String(row.quantity || "-"), qtyX, y + 22, { align: "center" });

      // Amount (right)
      const amtX = margin + colDescW + colQtyW + colAmtW - 14;
      doc.text(formatCurrency(row.value), amtX, y + 22, { align: "right" });

      // Divider
      doc.setDrawColor(border.r, border.g, border.b);
      doc.setLineWidth(0.5);
      doc.line(margin, y + rowH, margin + contentWidth, y + rowH);

      y += rowH;
    });

    return y + 12;
  };

  const drawTotals = (startY) => {
    const cardW = 260;
    const x = margin + contentWidth - cardW;
    const h = 130;

    // Reserve space so totals don't overlap the footer.
    // Only push to a new page on pages AFTER the first; on the first page
    // we prefer to keep totals + footer together even if space is tight.
    const currentPage = doc.internal.getNumberOfPages();
    const footerY = pageHeight - 40; // should match footerY in drawFooter
    const gapAboveFooter = 24; // breathing room between totals and footer
    const maxStartY = footerY - gapAboveFooter - h;

    if (currentPage > 1 && startY > maxStartY) {
      // Move totals to the next page near the top if they would collide
      doc.addPage();
      startY = margin + 40;
    }

    doc.setFillColor(light.r, light.g, light.b);
    doc.roundedRect(x, startY, cardW, h, 10, 10, "F");

  doc.setFont("helvetica", "normal");
    doc.setFontSize(11);
    doc.setTextColor(medium.r, medium.g, medium.b);
    doc.text("Subtotal", x + 20, startY + 30);
    doc.text(
      formatCurrency(totalValue),
      x + cardW - 20,
      startY + 30,
      { align: "right" }
    );

    doc.text("Tax (0%)", x + 20, startY + 52);
    doc.text(
      formatCurrency(0),
      x + cardW - 20,
      startY + 52,
      { align: "right" }
    );

    // Divider
    doc.setDrawColor(border.r, border.g, border.b);
    doc.setLineWidth(1);
    doc.line(x + 20, startY + 70, x + cardW - 20, startY + 70);

    // Total
    doc.setFont("helvetica", "bold");
    doc.setFontSize(13);
    doc.setTextColor(medium.r, medium.g, medium.b);
    doc.text("TOTAL DUE", x + 20, startY + 96);

    // Total amount with blue highlight box
    const totalText = formatCurrency(totalValue);
    doc.setFontSize(18);
    doc.setTextColor(white.r, white.g, white.b);
    const totalWidth = doc.getTextWidth(totalText);
    const paddingX = 10;
    const paddingY = 6;
    const boxRight = x + cardW - 20;
    const boxTop = startY + 82;
    const boxWidth = totalWidth + paddingX * 2;
    const boxHeight = 24 + paddingY;

    // Blue box behind total amount
    doc.setFillColor(primary.r, primary.g, primary.b);
    doc.roundedRect(
      boxRight - boxWidth,
      boxTop,
      boxWidth,
      boxHeight,
      6,
      6,
      "F"
    );

    // Total text centered vertically inside box, right aligned
    const textY = boxTop + boxHeight / 2 + 5;
    doc.text(totalText, boxRight - paddingX, textY, { align: "right" });

    return startY + h + 20;
  };

  const drawFooter = () => {
    const footerY = pageHeight - 40;

    // Thin divider
    doc.setDrawColor(border.r, border.g, border.b);
    doc.setLineWidth(0.8);
    doc.line(margin, footerY - 18, margin + contentWidth, footerY - 18);

    const centerX = pageWidth / 2;

    // Center thank-you + contact stacked
  doc.setFont("helvetica", "normal");
  doc.setFontSize(10);
    doc.setTextColor(medium.r, medium.g, medium.b);
    doc.text("Thank you for your business.", centerX, footerY - 2, {
      align: "center",
    });

    doc.setFontSize(9);
  doc.text(
      "support@nexvoide.com  •  +92 336 455 8535  •  www.nexvoide.com",
      centerX,
      footerY + 12,
      { align: "center" }
    );
  };

  // Render document
  drawHeader();
  let y = drawFromTo();
  y = drawMetaCards(y);
  y = drawProjectsTable(y);
  y = drawTotals(y);
  drawFooter();

  const sanitizedName = (entity.name || "invoice")
    .replace(/[^a-z0-9]/gi, "_")
    .toLowerCase();
  const filename = `${sanitizedName}_${currentMonth}_invoice.pdf`;
  doc.save(filename);

  return {
    projectCount: projectRows.length,
    totalValue,
    currency,
    filename,
  };
}

/**
 * Generate a Salary PDF for a single employee for the current month.
 * Lists: Project Name, Quantity, Employee Cost, and totals.
 */
export function generateSalaryPDF(
  employee,
  projects,
  currency = "PKR",
  rate = 280
) {
  const doc = new jsPDF("p", "pt", "a4");
  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();
  const margin = 40;
  const contentWidth = pageWidth - margin * 2;

  // Premium color palette (matching invoice)
  const COLORS = {
    primary: "#1a56db", // deep blue
    secondary: "#1a56db", // blue for totals
    dark: "#020617",
    medium: "#64748b",
    light: "#f3f4f6",
    border: "#e5e7eb",
    white: "#ffffff",
  };
  const hexToRgb = (h) => {
    h = h.replace("#", "");
    const b = parseInt(h, 16);
    if (h.length === 6) {
      return { r: (b >> 16) & 255, g: (b >> 8) & 255, b: b & 255 };
    }
    return { r: 0, g: 0, b: 0 };
  };

  const now = new Date();
  const currentMonth = `${now.getFullYear()}-${String(
    now.getMonth() + 1
  ).padStart(2, "0")}`;
  const monthName = now.toLocaleString("default", {
    month: "long",
    year: "numeric",
  });

  // Convert helper
  const convertCurrency = (amount, fromCurrency) => {
    const n = Number(amount) || 0;
    if (fromCurrency === currency) return n;
    if (fromCurrency === "USD" && currency === "PKR") return n * rate;
    if (fromCurrency === "PKR" && currency === "USD") return n / rate;
    return n;
  };

  // Filter projects in current month where employee is assigned
  const inMonth = (p) => {
    const d = p.endDate || p.end_date || p.startDate || p.start_date;
    if (!d) return false;
    const dt = new Date(d);
    if (isNaN(dt)) return false;
    const ym = `${dt.getFullYear()}-${String(dt.getMonth() + 1).padStart(
      2,
      "0"
    )}`;
    return ym === currentMonth;
  };

  // Normalize assigned field
  const ensureAssigned = (assigned) => {
    if (Array.isArray(assigned)) return assigned;
    if (typeof assigned === "string") {
      try {
        const a = JSON.parse(assigned);
        return Array.isArray(a) ? a : [];
      } catch {
        return [];
      }
    }
    return [];
  };

  // Build rows where this employee appears
  const rows = [];
  for (const p of projects.filter(inMonth)) {
    const assigned = ensureAssigned(p.assigned);
    const found = assigned.find((a) => a?.name === employee.name);
    if (!found) continue;
    // Compute employee cost for this project in display currency
    const orderDisplay = convertCurrency(p.amount || 0, p.currency || "USD");
    let empCost = 0;
    if (found.costType === "percentage") {
      empCost = orderDisplay * ((Number(found.costValue) || 0) / 100);
    } else {
      // fixed in PKR originally
      empCost = convertCurrency(found.costValue || 0, "PKR");
    }
    const quantity =
      (p.isRevision ? p.revisionQuantity || p.revision_quantity : p.quantity) ||
      "-";
    const projectName = p.projectName || p.project_name || "Unnamed Project";
    rows.push({ name: projectName, quantity, cost: empCost });
  }

  // Color variables (matching invoice)
  const primary = hexToRgb(COLORS.primary);
  const secondary = hexToRgb(COLORS.secondary);
  const dark = hexToRgb(COLORS.dark);
  const medium = hexToRgb(COLORS.medium);
  const light = hexToRgb(COLORS.light);
  const border = hexToRgb(COLORS.border);
  const white = hexToRgb(COLORS.white);

  const formatCurrency = (amount) =>
    new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: currency === "PKR" ? "PKR" : "USD",
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }).format(amount);

  // ===== Header - match invoice style (dark bar + logo + right block) =====
  const headerH = 90;
  // Full-width dark header (same as invoice: #010333)
  doc.setFillColor(1, 3, 51);
  doc.rect(0, 0, pageWidth, headerH, "F");

  // Logo (reuse global Nexvoide logo if available)
  const logoY = 24;
  if (NEXVOIDE_LOGO_DATA_URL) {
    const logoWidth = 146;
    const logoHeight = 32;
    try {
      doc.addImage(
        NEXVOIDE_LOGO_DATA_URL,
        "PNG",
        margin,
        logoY,
        logoWidth,
        logoHeight
      );
    } catch {
      doc.setFont("helvetica", "bold");
      doc.setFontSize(22);
      doc.setTextColor(255, 255, 255);
      doc.text("NEXVOIDE", margin, 32);
    }
  } else {
    doc.setFont("helvetica", "bold");
    doc.setFontSize(22);
    doc.setTextColor(255, 255, 255);
    doc.text("NEXVOIDE", margin, 32);
  }

  // Right side: "SALARY SLIP", slip number and period
  const rightX = pageWidth - margin;

  doc.setFont("helvetica", "bold");
  doc.setFontSize(16);
  doc.setTextColor(255, 255, 255);
  doc.text("SALARY SLIP", rightX, 38, { align: "right" });

  const salaryNum = `SAL-${now.getFullYear()}-${String(
    now.getMonth() + 1
  ).padStart(2, "0")}${String(now.getDate()).padStart(2, "0")}`;
  doc.setFont("helvetica", "normal");
  doc.setFontSize(10);
  doc.setTextColor(199, 210, 254);
  doc.text(salaryNum, rightX, 54, { align: "right" });

  doc.setFontSize(9.5);
  doc.setTextColor(148, 163, 184);
  doc.text(`Period: ${monthName}`, rightX, 68, { align: "right" });

  // Start content below header
  const contentStartY = headerH + 20;

  // === FROM/TO section (matching invoice style) ===
  const drawFromTo = () => {
    let yPos = headerH + 20;

    // From (company)
    const boxH = 90;
    const halfW = (contentWidth - 10) / 2;

    doc.setFillColor(light.r, light.g, light.b);
    doc.roundedRect(margin, yPos, halfW, boxH, 8, 8, "F");

    doc.setFont("helvetica", "bold");
    doc.setFontSize(9);
    doc.setTextColor(medium.r, medium.g, medium.b);
    doc.text("FROM", margin + 18, yPos + 20);

    doc.setFont("helvetica", "bold");
    doc.setFontSize(15);
    doc.setTextColor(dark.r, dark.g, dark.b);
    doc.text("Nexvoide", margin + 18, yPos + 38);

    doc.setFont("helvetica", "normal");
    doc.setFontSize(10);
    doc.setTextColor(medium.r, medium.g, medium.b);
    doc.text("Suite 101, Tech Park", margin + 18, yPos + 56);
    doc.text("Lahore, Punjab 54000", margin + 18, yPos + 70);
    doc.text("support@nexvoide.com", margin + 18, yPos + 84);

    // To (employee)
    const toX = margin + halfW + 10;
    doc.setFillColor(light.r, light.g, light.b);
    doc.roundedRect(toX, yPos, halfW, boxH, 8, 8, "F");

    doc.setFont("helvetica", "bold");
    doc.setFontSize(9);
    doc.setTextColor(medium.r, medium.g, medium.b);
    doc.text("EMPLOYEE", toX + 18, yPos + 20);

    doc.setFont("helvetica", "bold");
    doc.setFontSize(15);
    doc.setTextColor(dark.r, dark.g, dark.b);
    const employeeName = doc.splitTextToSize(
      String(employee.name || "Employee").toUpperCase(),
      halfW - 36
    );
    doc.text(employeeName, toX + 18, yPos + 38);

    if (employee.email) {
      doc.setFont("helvetica", "normal");
      doc.setFontSize(10);
      doc.setTextColor(medium.r, medium.g, medium.b);
      doc.text(employee.email, toX + 18, yPos + 56);
    }

    if (employee.role) {
      doc.text(employee.role, toX + 18, yPos + 70);
    }

    return yPos + boxH + 20;
  };

  // === Meta cards section (matching invoice style) ===
  const drawMetaCards = (startY) => {
    const details = [
      { label: "PAY PERIOD", value: monthName },
      { label: "ISSUE DATE", value: now.toISOString().slice(0, 10) },
      { label: "PAYMENT DATE", 
        value: new Date(now.getFullYear(), now.getMonth() + 1, 15)
          .toISOString().slice(0, 10) },
      { label: "CURRENCY", value: currency },
    ];

    const boxWidth = (contentWidth - 30) / 4;
    
    details.forEach((detail, index) => {
      const x = margin + index * (boxWidth + 10);
      
      doc.setFillColor(255, 255, 255);
      doc.setDrawColor(border.r, border.g, border.b);
      doc.setLineWidth(1);
      doc.roundedRect(x, startY, boxWidth, 70, 6, 6, "FD");

      doc.setFont("helvetica", "bold");
      doc.setFontSize(9);
      doc.setTextColor(primary.r, primary.g, primary.b);
      const labelWidth = doc.getTextWidth(detail.label);
      doc.text(detail.label, x + (boxWidth - labelWidth) / 2, startY + 20);

      doc.setFont("helvetica", "bold");
      doc.setFontSize(14);
      doc.setTextColor(dark.r, dark.g, dark.b);
      const valueWidth = doc.getTextWidth(detail.value);
      doc.text(detail.value, x + (boxWidth - valueWidth) / 2, startY + 45);
    });

    return startY + 90;
  };

  // === Table section (matching invoice exactly) ===
  const drawProjectsTable = (startY) => {
    const headerH = 40;
    const rowH = 40;

    const colDescW = contentWidth * 0.5;
    const colQtyW = contentWidth * 0.15;
    const colAmtW = contentWidth * 0.35;

    const tableTop = startY + 10;

    // Header background (dark blue like invoice)
    doc.setFillColor(primary.r, primary.g, primary.b);
    doc.roundedRect(margin, tableTop, contentWidth, headerH, 6, 6, "F");

    doc.setFont("helvetica", "bold");
    doc.setFontSize(10.5);
    doc.setTextColor(white.r, white.g, white.b);

    let x = margin + 14;
    const headerY = tableTop + 20;
    doc.text("DESCRIPTION", x, headerY);

    x = margin + colDescW + colQtyW / 2;
    doc.text("QTY", x, headerY, { align: "center" });

    x = margin + colDescW + colQtyW + colAmtW - 14;
    doc.text("AMOUNT", x, headerY, { align: "right" });

    let y = tableTop + headerH;

    if (rows.length === 0) {
      y += 24;
      doc.setFont("helvetica", "normal");
      doc.setFontSize(11);
      doc.setTextColor(medium.r, medium.g, medium.b);
      doc.text(
        "No projects assigned for this period.",
        margin + contentWidth / 2,
        y,
        { align: "center" }
      );
      y += 40;
      return y;
    }

    let totalCost = 0;
    rows.forEach((row, idx) => {
      if (y > pageHeight - 160) {
        doc.addPage();
        y = margin + 40;
      }

      // zebra stripe (alternating light gray/white)
      if (idx % 2 === 0) {
        doc.setFillColor(248, 250, 252);
        doc.rect(margin, y, contentWidth, rowH, "F");
      }

      doc.setFont("helvetica", "normal");
      doc.setFontSize(11);
      doc.setTextColor(dark.r, dark.g, dark.b);

      // Description
      const desc = doc.splitTextToSize(String(row.name || ""), colDescW - 24);
      doc.text(desc, margin + 14, y + 22);

      // Qty (center)
      const qtyX = margin + colDescW + colQtyW / 2;
      doc.text(String(row.quantity || "-"), qtyX, y + 22, { align: "center" });

      // Amount (right)
      const amtX = margin + colDescW + colQtyW + colAmtW - 14;
      doc.text(formatCurrency(row.cost), amtX, y + 22, { align: "right" });

      totalCost += Number(row.cost) || 0;

      // Divider
      doc.setDrawColor(border.r, border.g, border.b);
      doc.setLineWidth(0.5);
      doc.line(margin, y + rowH, margin + contentWidth, y + rowH);

      y += rowH;
    });

    // Store totalCost for totals section
    window._salaryTotalCost = totalCost;
    return y + 12;
  };

  // === Totals section (matching invoice exactly) ===
  const drawTotals = (startY) => {
    const cardW = 260;
    const x = margin + contentWidth - cardW;
    const h = 130;

    // Reserve space so totals don't overlap the footer.
    // Only push to a new page on pages AFTER the first; on the first page
    // we prefer to keep totals + footer together even if space is tight.
    const currentPage = doc.internal.getNumberOfPages();
    const footerY = pageHeight - 40; // matches footerY in drawFooter
    const gapAboveFooter = 24; // breathing room between totals and footer
    const maxStartY = footerY - gapAboveFooter - h;

    if (currentPage > 1 && startY > maxStartY) {
      // Move totals to the next page near the top if they would collide
      doc.addPage();
      startY = margin + 40;
    }

    const totalCost = window._salaryTotalCost || 0;

    doc.setFillColor(light.r, light.g, light.b);
    doc.roundedRect(x, startY, cardW, h, 10, 10, "F");

    doc.setFont("helvetica", "normal");
    doc.setFontSize(11);
    doc.setTextColor(medium.r, medium.g, medium.b);
    doc.text("Subtotal", x + 20, startY + 30);
    doc.text(
      formatCurrency(totalCost),
      x + cardW - 20,
      startY + 30,
      { align: "right" }
    );

    doc.text("Tax (0%)", x + 20, startY + 52);
    doc.text(
      formatCurrency(0),
      x + cardW - 20,
      startY + 52,
      { align: "right" }
    );

    // Divider
    doc.setDrawColor(border.r, border.g, border.b);
    doc.setLineWidth(1);
    doc.line(x + 20, startY + 70, x + cardW - 20, startY + 70);

    // Total
    doc.setFont("helvetica", "bold");
    doc.setFontSize(13);
    doc.setTextColor(medium.r, medium.g, medium.b);
    doc.text("TOTAL DUE", x + 20, startY + 96);

    // Total amount with blue highlight box
    const totalText = formatCurrency(totalCost);
    doc.setFontSize(16);
    doc.setTextColor(white.r, white.g, white.b);
    const totalWidth = doc.getTextWidth(totalText);
    const paddingX = 10;
    const paddingY = 6;
    const boxRight = x + cardW - 20;
    const boxTop = startY + 82; // Aligned with invoice version
    const boxWidth = totalWidth + paddingX * 2;
    const boxHeight = 24 + paddingY;

    // Blue box behind total amount
    doc.setFillColor(primary.r, primary.g, primary.b);
    doc.roundedRect(
      boxRight - boxWidth,
      boxTop,
      boxWidth,
      boxHeight,
      6,
      6,
      "F"
    );

    // Total text centered vertically inside box, right aligned
    const textY = boxTop + boxHeight / 2 + 5;
    doc.text(totalText, boxRight - paddingX, textY, { align: "right" });

    return startY + h + 20;
  };

  // === Footer section (matching invoice exactly) ===
  const drawFooter = () => {
    const footerY = pageHeight - 40;

    // Thin divider
    doc.setDrawColor(border.r, border.g, border.b);
    doc.setLineWidth(0.8);
    doc.line(margin, footerY - 18, margin + contentWidth, footerY - 18);

    const centerX = pageWidth / 2;

    // Center thank-you + contact stacked
    doc.setFont("helvetica", "normal");
    doc.setFontSize(10);
    doc.setTextColor(medium.r, medium.g, medium.b);
    doc.text("Thank you for your dedication!", centerX, footerY - 2, {
      align: "center",
    });

    doc.setFontSize(9);
    doc.text(
      "support@nexvoide.com  •  +92 336 455 8535  •  www.nexvoide.com",
      centerX,
      footerY + 12,
      { align: "center" }
    );
  };

  // === Render document ===
  // Header is already drawn above
  let y = drawFromTo();
  y = drawMetaCards(y);
  y = drawProjectsTable(y);
  y = drawTotals(y);
  drawFooter();

  // Generate filename
  const totalCost = window._salaryTotalCost || 0;
  delete window._salaryTotalCost; // cleanup
  const file = `${(employee.name || "employee")
    .replace(/[^a-z0-9]/gi, "_")
    .toLowerCase()}_${currentMonth}_salary.pdf`;
  doc.save(file);
  return { rows: rows.length, totalCost, currency };
}

// =============== Simple HTML-based generators ==================

function openHtmlDocument(html) {
  const w = window.open("", "_blank");
  if (!w) return;
  w.document.open();
  w.document.write(html);
  w.document.close();
  // Give time to render then trigger print (user can select Save as PDF)
  setTimeout(() => {
    try {
      w.focus();
      w.print();
    } catch (_) {}
  }, 400);
}

function currencyFormat(n, currency) {
  try {
    return (
      new Intl.NumberFormat("en", {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      }).format(Number(n) || 0) +
      " " +
      currency
    );
  } catch {
    return String(n) + " " + currency;
  }
}

export function generateInvoiceHTML(
  entity,
  projects,
  entityType,
  currency = "PKR",
  rate = 280
) {
  const now = new Date();
  const monthName = now.toLocaleString("default", {
    month: "long",
    year: "numeric",
  });
  const inMonth = (p) => {
    const d = p.endDate || p.end_date || p.startDate || p.start_date;
    if (!d) return false;
    const dt = new Date(d);
    if (isNaN(dt)) return false;
    const ym = `${dt.getFullYear()}-${String(dt.getMonth() + 1).padStart(
      2,
      "0"
    )}`;
    const thisYm = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(
      2,
      "0"
    )}`;
    return ym === thisYm;
  };
  const convert = (amt, from) => {
    const n = Number(amt) || 0;
    if (from === currency) return n;
    if (from === "USD" && currency === "PKR") return n * rate;
    if (from === "PKR" && currency === "USD") return n / rate;
    return n;
  };
  const agencyId = entity.id;
  const rows = [];
  let total = 0;
  projects.filter(inMonth).forEach((p) => {
    const match =
      entityType === "agency"
        ? p.agencyId === agencyId || p.agency_id === agencyId
        : p.brandId === agencyId || p.brand_id === agencyId;
    if (!match) return;
    const name = p.projectName || p.project_name || "Unnamed Project";
    const qty = p.quantity || p.revisionQuantity || p.revision_quantity || "-";
    const amount = convert(p.amount || 0, p.currency || "USD");
    total += amount;
    rows.push({ name, qty, amount });
  });
  const itemsHtml = rows
    .map(
      (r) => `
      <tr>
        <td class="desc">${r.name}</td>
        <td class="qty">${r.qty}</td>
        <td class="amt">${currencyFormat(r.amount, currency)}</td>
      </tr>
  `
    )
    .join("");

  const html = `<!doctype html><html><head><meta charset="utf-8"/>
  <title>Invoice</title>
  <style>
    :root{ --blue:#2642FF; --dark:#001033; --muted:#8A93A6; --line:#e9edf5; }
    *{ box-sizing:border-box; }
    body{ font-family: -apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Inter,Helvetica,Arial; margin:24px; color:#111827; }
    .card{ border:1px solid var(--line); border-radius:12px; padding:14px 16px; background:#fff; }
    .row{ display:flex; gap:16px; }
    .col{ flex:1; }
    .muted{ color:var(--muted); font-weight:600; font-size:11px; letter-spacing:.08em; text-transform:uppercase; }
    h1{ margin:0 0 6px; font-size:26px; }
    table{ width:100%; border-collapse:separate; border-spacing:0; }
    thead th{ text-align:left; color:var(--muted); font-size:12px; padding:12px 14px; background:#f8fafc; }
    tbody td{ padding:12px 14px; border-top:1px solid var(--line); font-size:13px; }
    .desc{ width:60%; }
    .qty{ width:15%; }
    .amt{ width:25%; text-align:right; }
    .badge{ background:#eef2ff; border-radius:10px; display:inline-block; padding:6px 10px; color:#fff; }
    .btn{ background:var(--blue); color:#fff; padding:10px 14px; border-radius:10px; display:inline-block; font-weight:700; }
    .total{ text-align:right; font-weight:700; }
  </style></head><body>
    <div class="row" style="align-items:center; justify-content:space-between; margin-bottom:18px;">
      <div>
        <h1>Nexvoide</h1>
        <div class="muted">Invoice Statement</div>
      </div>
      <div class="card" style="min-width:220px; text-align:center;">
        <div class="muted" style="margin-bottom:6px;">Invoice #</div>
        <div class="btn">INV-${now.getFullYear()}-${String(
    now.getMonth() + 1
  ).padStart(2, "0")}${String(now.getDate()).padStart(2, "0")}</div>
      </div>
    </div>

    <div class="card" style="margin-bottom:18px;">
      <div class="row">
        <div class="col">
          <div class="muted">From</div>
          <div style="font-weight:700; margin:6px 0;">Nexvoide</div>
          <div>Suite 101, Tech Park</div><div>Lahore, Punjab</div><div>Pakistan</div>
        </div>
        <div class="col">
          <div class="muted">To</div>
          <div style="font-weight:700; margin:6px 0;">${entity.name || ""}</div>
          ${entity.street ? `<div>${entity.street}</div>` : ""}
          ${
            entity.city || entity.state || entity.zip
              ? `<div>${[entity.city, entity.state, entity.zip]
                  .filter(Boolean)
                  .join(", ")}</div>`
              : ""
          }
          ${entity.country ? `<div>${entity.country}</div>` : ""}
        </div>
      </div>
      <div class="row" style="margin-top:12px;">
        <div class="card col"><div class="muted">Pay Period</div><div style="font-weight:700; font-size:16px; margin-top:6px;">${monthName}</div></div>
        <div class="card col"><div class="muted">Issue Date</div><div style="font-weight:700; font-size:16px; margin-top:6px;">${now
          .toISOString()
          .slice(0, 10)}</div></div>
        <div class="card col"><div class="muted">Due Date</div><div style="font-weight:700; font-size:16px; margin-top:6px;">${new Date(
          now.getFullYear(),
          now.getMonth(),
          now.getDate() + 15
        )
          .toISOString()
          .slice(0, 10)}</div></div>
        <div class="card col"><div class="muted">Service</div><div style="font-weight:700; font-size:16px; margin-top:6px;">${
          entity.service || ""
        }</div></div>
      </div>
    </div>

    <table>
      <thead><tr><th class="desc">Description</th><th class="qty">Qty</th><th class="amt">Amount</th></tr></thead>
      <tbody>${
        itemsHtml ||
        '<tr><td colspan="3" style="text-align:center; padding:24px; color:#94a3b8;">No items this month</td></tr>'
      }</tbody>
    </table>

    <div class="card" style="margin-top:18px;">
      <div class="row" style="align-items:center;">
        <div class="col"></div>
        <div class="col" style="text-align:right;">
          <div style="margin-bottom:8px; color:#64748b;">Subtotal</div>
          <div class="total" style="margin-bottom:8px;">${currencyFormat(
            total,
            currency
          )}</div>
          <div style="margin-top:10px;"><span class="btn">${currencyFormat(
            total,
            currency
          )}</span></div>
        </div>
      </div>
    </div>

    <div style="display:flex; gap:24px; margin-top:22px; color:#64748b;">
      <div style="flex:1;">
        <div class="muted">Payment Methods</div>
        <div style="margin-top:6px;">Payoneer · Binance · Remitly · WireTransfer</div>
      </div>
      <div style="flex:1;">
        <div class="muted">Terms & Conditions</div>
        <div style="margin-top:6px;">No transaction fees or taxes apply on Nexvoide.</div>
      </div>
    </div>
  </body></html>`;
  openHtmlDocument(html);
}

export function generateSalaryHTML(
  employee,
  projects,
  currency = "PKR",
  rate = 280
) {
  const now = new Date();
  const monthName = now.toLocaleString("default", {
    month: "long",
    year: "numeric",
  });
  const inMonth = (p) => {
    const d = p.endDate || p.end_date || p.startDate || p.start_date;
    if (!d) return false;
    const dt = new Date(d);
    if (isNaN(dt)) return false;
    const ym = `${dt.getFullYear()}-${String(dt.getMonth() + 1).padStart(
      2,
      "0"
    )}`;
    const thisYm = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(
      2,
      "0"
    )}`;
    return ym === thisYm;
  };
  const convert = (amt, from) => {
    const n = Number(amt) || 0;
    if (from === currency) return n;
    if (from === "USD" && currency === "PKR") return n * rate;
    if (from === "PKR" && currency === "USD") return n / rate;
    return n;
  };
  const ensureAssigned = (assigned) =>
    Array.isArray(assigned)
      ? assigned
      : typeof assigned === "string"
      ? (() => {
          try {
            const a = JSON.parse(assigned);
            return Array.isArray(a) ? a : [];
          } catch {
            return [];
          }
        })()
      : [];
  const rows = [];
  let total = 0;
  projects.filter(inMonth).forEach((p) => {
    const assigned = ensureAssigned(p.assigned);
    const found = assigned.find((a) => a?.name === employee.name);
    if (!found) return;
    const orderDisplay = convert(p.amount || 0, p.currency || "USD");
    const cost =
      found.costType === "percentage"
        ? orderDisplay * ((Number(found.costValue) || 0) / 100)
        : convert(found.costValue || 0, "PKR");
    const qty =
      (p.isRevision ? p.revisionQuantity || p.revision_quantity : p.quantity) ||
      "-";
    const name = p.projectName || p.project_name || "Unnamed Project";
    total += cost;
    rows.push({ name, qty, cost });
  });
  const itemsHtml = rows
    .map(
      (r) => `
      <tr>
        <td class="desc">${r.name}</td>
        <td class="qty">${r.qty}</td>
        <td class="amt">${currencyFormat(r.cost, currency)}</td>
      </tr>
  `
    )
    .join("");

  const html = `<!doctype html><html><head><meta charset="utf-8"/>
  <title>Salary</title>
  <style>
    :root{ --blue:#2642FF; --dark:#001033; --muted:#8A93A6; --line:#e9edf5; }
    *{ box-sizing:border-box; }
    body{ font-family: -apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Inter,Helvetica,Arial; margin:24px; color:#111827; }
    .card{ border:1px solid var(--line); border-radius:12px; padding:14px 16px; background:#fff; }
    .row{ display:flex; gap:16px; }
    .col{ flex:1; }
    .muted{ color:var(--muted); font-weight:600; font-size:11px; letter-spacing:.08em; text-transform:uppercase; }
    h1{ margin:0 0 6px; font-size:26px; }
    table{ width:100%; border-collapse:separate; border-spacing:0; }
    thead th{ text-align:left; color:var(--muted); font-size:12px; padding:12px 14px; background:#f8fafc; }
    tbody td{ padding:12px 14px; border-top:1px solid var(--line); font-size:13px; }
    .desc{ width:60%; }
    .qty{ width:15%; }
    .amt{ width:25%; text-align:right; }
    .btn{ background:var(--blue); color:#fff; padding:10px 14px; border-radius:10px; display:inline-block; font-weight:700; }
    .total{ text-align:right; font-weight:700; }
  </style></head><body>
    <div class="row" style="align-items:center; justify-content:space-between; margin-bottom:18px;">
      <div>
        <h1>Nexvoide</h1>
        <div class="muted">Salary Statement</div>
      </div>
      <div class="card" style="min-width:220px; text-align:center;">
        <div class="muted" style="margin-bottom:6px;">Period</div>
        <div class="btn">${monthName}</div>
      </div>
    </div>

    <div class="card" style="margin-bottom:18px;">
      <div class="row">
        <div class="col">
          <div class="muted">Employee</div>
          <div style="font-weight:700; margin:6px 0;">${
            employee.name || ""
          }</div>
          <div>${employee.role || ""}</div>
        </div>
        <div class="col">
          <div class="muted">Currency</div>
          <div style="font-weight:700; margin:6px 0;">${currency}</div>
          <div class="muted">Rate</div>
          <div>${rate}</div>
        </div>
      </div>
    </div>

    <table>
      <thead><tr><th class="desc">Description</th><th class="qty">Qty</th><th class="amt">Employee Cost</th></tr></thead>
      <tbody>${
        itemsHtml ||
        '<tr><td colspan="3" style="text-align:center; padding:24px; color:#94a3b8;">No items this month</td></tr>'
      }</tbody>
    </table>

    <div class="card" style="margin-top:18px;">
      <div class="row" style="align-items:center;">
        <div class="col"></div>
        <div class="col" style="text-align:right;">
          <div style="margin-bottom:8px; color:#64748b;">Total Salary</div>
          <div class="total" style="margin-bottom:8px;">${currencyFormat(
            total,
            currency
          )}</div>
          <div style="margin-top:10px;"><span class="btn">${currencyFormat(
            total,
            currency
          )}</span></div>
        </div>
      </div>
    </div>
  </body></html>`;
  openHtmlDocument(html);
}
